  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:archive", orgResource(orgId));
  await labelRepo.deleteLabel(orgId, labelId);
}

/**
 * Folds `sourceLabelId` into `targetLabelId`: every issue carrying the source
 * label ends up carrying the target instead, and the source label is
 * removed. Same blast radius as `deleteLabel`, so it takes the same
 * permission.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("sourceLabelId and targetLabelId must be different labels");
  }

  const [source, target] = await Promise.all([
    labelRepo.findLabelById(input.orgId, input.sourceLabelId),
    labelRepo.findLabelById(input.orgId, input.targetLabelId),
  ]);
  requireFound(source, "Label", input.sourceLabelId);
  const targetLabel = requireFound(target, "Label", input.targetLabelId);

  const issuesRelabelled = await labelRepo.mergeLabels(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );

  return { label: targetLabel, issuesRelabelled };
}

